  async function preference(c,operation,minutes=0){
    preferencesBusy=true;inboxRevision++;
    try {
      await request('preference',{id:c.id,operation,minutes},true);
      inboxRevision++;preferencesChannel?.postMessage({changed:true});if(operation==='archive')shakeIcon(archiveToggle);
      if(['archive','hide','unread'].includes(operation))leaveConversation(c.id);
      if(inboxTask)await inboxTask;
      await refresh();
      if(['block','unblock'].includes(operation)&&!inbox.some(x=>requestView?x.incoming_request:!x.incoming_request&&Boolean(x.archived)===archiveView)){
        const moved=inbox.find(x=>x.id===c.id);if(moved){requestView=Boolean(moved.incoming_request);archiveView=Boolean(moved.archived);archiveControls();inboxSignature='';renderInbox();}
      }
      if(current?.id===c.id)await loadThread(null,true);
    } finally {preferencesBusy=false;}
  }
